            m = j.get("message",{})
            for c in m.get("content", []):
                if isinstance(c, dict) and c.get("type") == "tool_result":
                    r = c.get("content","")
                    if isinstance(r, list):
                        r = "".join([x.get("text","") for x in r if isinstance(x,dict) and x.get("type")=="text"])
